import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { authAPI } from '../../services/api';
import { Link } from 'react-router-dom';

const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    if (error) setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await authAPI.login(formData);
      const { user, token } = response.data;
      
      login(user, token);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Échec de la connexion. Veuillez réessayer.');
    } finally {
      setLoading(false);
    }
  };

  // Styles inline
  const styles = {
    authContainer: {
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: '2rem 1rem',
      background: 'linear-gradient(135deg, #dc3545 0%, #c82333 50%, #a71e2a 100%)',
      position: 'relative',
      overflow: 'hidden',
    },
    backgroundPattern: {
      position: 'absolute',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundImage: `
        radial-gradient(circle at 25% 25%, rgba(255, 255, 255, 0.1) 0%, transparent 50%),
        radial-gradient(circle at 75% 75%, rgba(255, 255, 255, 0.08) 0%, transparent 50%)
      `,
      backgroundSize: '100px 100px',
      animation: 'backgroundFloat 20s ease-in-out infinite',
    },
    card: {
      background: 'rgba(255, 255, 255, 0.98)',
      backdropFilter: 'blur(20px)',
      borderRadius: '20px',
      padding: '3rem 2.5rem',
      width: '100%',
      maxWidth: '420px',
      boxShadow: `
        0 25px 50px rgba(0, 0, 0, 0.25),
        0 0 0 1px rgba(255, 255, 255, 0.3)
      `,
      position: 'relative',
      zIndex: 1,
      transform: 'translateY(0)',
      transition: 'all 0.3s ease',
    },
    cardHeader: {
      textAlign: 'center',
      marginBottom: '2.5rem',
    },
    cardTitle: {
      fontSize: '2.2rem',
      fontWeight: '700',
      background: 'linear-gradient(135deg, #dc3545, #c82333)',
      WebkitBackgroundClip: 'text',
      WebkitTextFillColor: 'transparent',
      backgroundClip: 'text',
      marginBottom: '0.75rem',
    },
    cardSubtitle: {
      color: '#6c757d',
      fontSize: '1rem',
      fontWeight: '400',
      margin: 0,
      opacity: 0.8,
    },
    formGroup: {
      marginBottom: '1.8rem',
      position: 'relative',
    },
    formLabel: {
      display: 'block',
      fontWeight: '600',
      fontSize: '0.95rem',
      color: '#374151',
      marginBottom: '0.6rem',
      transition: 'color 0.2s ease',
    },
    formControl: {
      width: '100%',
      padding: '1rem 1.2rem',
      fontSize: '1rem',
      border: '2px solid #e5e7eb',
      borderRadius: '12px',
      backgroundColor: '#fafafa',
      transition: 'all 0.3s ease',
      fontFamily: 'inherit',
      outline: 'none',
    },
    formControlFocus: {
      borderColor: '#dc3545',
      backgroundColor: '#fff',
      boxShadow: '0 0 0 4px rgba(220, 53, 69, 0.1)',
      transform: 'translateY(-1px)',
    },
    btn: {
      width: '100%',
      padding: '1rem 1.5rem',
      border: 'none',
      borderRadius: '12px',
      fontSize: '1.1rem',
      fontWeight: '600',
      cursor: 'pointer',
      transition: 'all 0.3s ease',
      position: 'relative',
      overflow: 'hidden',
      marginTop: '0.5rem',
    },
    btnPrimary: {
      background: 'linear-gradient(135deg, #dc3545 0%, #c82333 100%)',
      color: 'white',
      boxShadow: '0 4px 15px rgba(220, 53, 69, 0.4)',
    },
    btnDisabled: {
      background: 'linear-gradient(135deg, #6c757d 0%, #5a6268 100%)',
      cursor: 'not-allowed',
      boxShadow: '0 4px 15px rgba(108, 117, 125, 0.3)',
    },
    errorMessage: {
      background: 'linear-gradient(135deg, #f8d7da, #f5c6cb)',
      color: '#721c24',
      padding: '1rem 1.2rem',
      borderRadius: '12px',
      marginBottom: '1.5rem',
      border: '1px solid #f1aeb5',
      fontWeight: '500',
      animation: 'slideIn 0.3s ease',
    },
    textCenter: {
      textAlign: 'center',
    },
    mt3: {
      marginTop: '1.5rem',
    },
    link: {
      color: '#dc3545',
      textDecoration: 'none',
      fontWeight: '600',
      transition: 'all 0.2s ease',
    },
    demoCredentials: {
      background: 'rgba(255, 255, 255, 0.15)',
      backdropFilter: 'blur(10px)',
      padding: '0.8rem 1.2rem',
      borderRadius: '10px',
      border: '1px solid rgba(255, 255, 255, 0.2)',
      fontSize: '0.85rem',
      fontWeight: '500',
      maxWidth: '420px',
      margin: '0 auto',
      color: 'rgba(255, 255, 255, 0.9)',
    },
    spinner: {
      display: 'inline-block',
      width: '20px',
      height: '20px',
      border: '2px solid transparent',
      borderTop: '2px solid #fff',
      borderRadius: '50%',
      animation: 'spin 1s linear infinite',
      marginLeft: '10px',
    }
  };

  return (
    <>
      <style>
        {`
          @keyframes backgroundFloat {
            0%, 100% { transform: translate(0, 0); }
            50% { transform: translate(-10px, -10px); }
          }
          
          @keyframes slideIn {
            from {
              opacity: 0;
              transform: translateY(-10px);
            }
            to {
              opacity: 1;
              transform: translateY(0);
            }
          }
          
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
          
          .auth-card:hover {
            transform: translateY(-5px) !important;
            box-shadow: 0 35px 70px rgba(0, 0, 0, 0.3), 0 0 0 1px rgba(255, 255, 255, 0.4) !important;
          }
          
          .auth-btn:hover:not(:disabled) {
            background: linear-gradient(135deg, #c82333 0%, #a71e2a 100%) !important;
            box-shadow: 0 6px 25px rgba(220, 53, 69, 0.6) !important;
            transform: translateY(-2px) !important;
          }
          
          .auth-btn:active {
            transform: translateY(0) !important;
            box-shadow: 0 2px 10px rgba(220, 53, 69, 0.4) !important;
          }
          
          .auth-link:hover {
            color: #c82333 !important;
          }
          
          .form-input:hover {
            border-color: #d1d5db !important;
            background-color: #fff !important;
          }
          
          @media (max-width: 480px) {
            .auth-container {
              padding: 1rem 0.5rem !important;
            }
            
            .auth-card {
              padding: 2rem 1.5rem !important;
              margin: 0 0.5rem !important;
              border-radius: 16px !important;
            }
            
            .card-title {
              font-size: 1.8rem !important;
            }
          }
        `}
      </style>
      
      <div style={styles.authContainer} className="auth-container">
        <div style={styles.backgroundPattern}></div>
        
        <div style={styles.card} className="auth-card">
          <div style={styles.cardHeader}>
            <h2 style={styles.cardTitle} className="card-title">Bienvenue</h2>
            <p style={styles.cardSubtitle}>
              Connectez-vous à votre compte Tunisair Academy
            </p>
          </div>
          
          <form onSubmit={handleSubmit}>
            {error && (
              <div style={styles.errorMessage}>
                {error}
              </div>
            )}
            
            <div style={styles.formGroup}>
              <label htmlFor="email" style={styles.formLabel}>
                Email
              </label>
              <input
                type="email"
                id="email"
                name="email"
                style={{
                  ...styles.formControl,
                  ...(document.activeElement?.name === 'email' ? styles.formControlFocus : {})
                }}
                className="form-input"
                value={formData.email}
                onChange={handleChange}
                required
                placeholder="Entrez votre email"
                autoComplete="email"
              />
            </div>
            
            <div style={styles.formGroup}>
              <label htmlFor="password" style={styles.formLabel}>
                Mot de passe
              </label>
              <input
                type="password"
                id="password"
                name="password"
                style={{
                  ...styles.formControl,
                  ...(document.activeElement?.name === 'password' ? styles.formControlFocus : {})
                }}
                className="form-input"
                value={formData.password}
                onChange={handleChange}
                required
                placeholder="Entrez votre mot de passe"
                autoComplete="current-password"
              />
            </div>
            
            <button
              type="submit"
              style={{
                ...styles.btn,
                ...(loading ? styles.btnDisabled : styles.btnPrimary)
              }}
              className="auth-btn"
              disabled={loading}
            >
              {loading ? (
                <>
                  Connexion en cours...
                  <span style={styles.spinner}></span>
                </>
              ) : 'Se connecter'}
            </button>
          </form>
          
          <div style={{...styles.textCenter, ...styles.mt3}}>
            <p style={{margin: 0, color: '#6c757d', fontSize: '0.9rem'}}>
              Vous n'avez pas de compte ?{' '}
              <Link to="/signup" style={styles.link} className="auth-link">
                Inscrivez-vous ici
              </Link>
            </p>
          </div>
        </div>
        
        <div style={{...styles.textCenter, ...styles.mt3}}>
          <p style={styles.demoCredentials}>
            <strong>Identifiants de démonstration :</strong><br />
            Email: admin@example.com | Mot de passe: password123
          </p>
        </div>
      </div>
    </>
  );
};

export default Login;
